with c as (select id from public.academy_courses where id='meteorology-forecasting-foundations'),
ch as (insert into public.academy_chapters(course_id,title,description,sort_order,published) select id,'النماذج العددية المتقدمة والذكاء الاصطناعي في الأرصاد','النماذج الإقليمية وعالية الدقة واستيعاب الرادار والأقمار والتصغير المكاني والتعلم الآلي وحوكمته.',22,false from c on conflict(course_id,title) do update set description=excluded.description returning id),
u1 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'النماذج العددية المتقدمة',1,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u2 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'الاستيعاب المتقدم للبيانات',2,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u3 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'الذكاء الاصطناعي والأرصاد',3,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
d(slug,title,summary,content,ord,mins,objectives,unit) as (values ('regional-nwp-and-domain-nesting','النماذج العددية الإقليمية وتقنيات التداخل الشبكي','النماذج محدودة المجال والشروط الحدية والشبكات المتداخلة.','{"blocks":[{"type":"text","text":"تستخدم النماذج الإقليمية لمحاكاة مجال جغرافي محدود بدقة مكانية أعلى من بعض النماذج العالمية."},{"type":"text","text":"تحتاج النماذج محدودة المجال إلى شروط حدية جانبية توفرها عادة مخرجات نموذج أكبر."},{"type":"text","text":"تؤثر جودة النموذج العالمي والتهيئة الأولية في جودة التنبؤ الإقليمي."},{"type":"text","text":"تستخدم الشبكات المتداخلة لتشغيل مجال فرعي بدقة أعلى داخل مجال أوسع، مع تبادل المعلومات وفق تصميم النموذج."},{"type":"text","text":"قد تكون الشبكات المتداخلة أحادية الاتجاه أو ثنائية الاتجاه بحسب طريقة تبادل المعلومات بين المجالات."},{"type":"text","text":"تسمح الدقة الأعلى بتمثيل تضاريس وتباينات محلية أفضل، لكنها لا تضمن تلقائياً مهارة أعلى."},{"type":"text","text":"تزداد الكلفة الحسابية مع زيادة الدقة الأفقية والرأسية وتقليل الخطوة الزمنية."},{"type":"text","text":"تتطلب النماذج الإقليمية تمثيل مناسب للسطح والبحر والغطاء الأرضي والعمليات الفيزيائية."},{"type":"text","text":"قد تنتشر أخطاء الشروط الحدية إلى داخل المجال مع الزمن، خاصة إذا كان المجال صغيراً أو التدفق سريعاً."},{"type":"text","text":"يجب تقييم أثر حجم المجال وموقع حدوده ودقة الشبكة على الظواهر المستهدفة."},{"type":"text","text":"مثال: نموذج إقليمي فوق حوض جبلي قد يحسن تمثيل التضاريس، لكنه يحتاج حدوداً عالمية جيدة وتمثيلاً مناسباً للسحب."},{"type":"callout","text":"خلاصة: النموذج الإقليمي منظومة تعتمد على جودة الحدود والتهيئة والشبكة والفيزياء معاً."}]}',1460,60,'["شرح النماذج الإقليمية","فهم الشروط الحدية","تمييز الشبكات المتداخلة"]','النماذج العددية المتقدمة'),
('convection-permitting-weather-models','النماذج عالية الدقة الممثلة للحمل الحراري','تمثيل السحب الحملية والهطول الموضعي والظواهر دون الشبكية.','{"blocks":[{"type":"text","text":"تستخدم النماذج الممثلة للحمل الحراري شبكات دقيقة بما يكفي لتمثيل جزء أكبر من الدوران الحملي العميق بصورة مباشرة."},{"type":"text","text":"تقل الحاجة إلى بعض مخططات الحمل التقليدية عند دقات معينة، لكن لا تختفي الحاجة إلى تمثيل السحب والعمليات الأصغر من الشبكة."},{"type":"text","text":"تؤثر الدقة الأفقية والرأسية والخطوة الزمنية في قدرة النموذج على تمثيل التيارات الصاعدة والهابطة."},{"type":"text","text":"قد تتحسن تفاصيل توقيت وموقع الهطول في بعض الحالات، لكن التنبؤ بخلايا مفردة يبقى حساساً للشروط الابتدائية."},{"type":"text","text":"تؤثر مخططات الميكروفيزياء والإشعاع والطبقة الحدية في تطور الحمل والهطول."},{"type":"text","text":"قد تظهر انحيازات في شدة الهطول أو توقيته أو تنظيم الخلايا بسبب أخطاء التمثيل والتهيئة."},{"type":"text","text":"تحتاج مخرجات النموذج إلى مقارنة بالرادار والأقمار والمحطات وليس إلى قبول مباشر."},{"type":"text","text":"تتطلب النماذج عالية الدقة موارد حسابية وبيانات أولية وحدية ذات جودة مناسبة."},{"type":"text","text":"لا تعني دقة الشبكة أن كل التفاصيل الصغيرة ممثلة فعلياً؛ إذ تبقى عمليات أصغر من الخلية الشبكية."},{"type":"text","text":"تستخدم مجموعات التنبؤ أو تعدد الفيزياء لتقدير حساسية الحمل والتوقيت والموقع."},{"type":"text","text":"مثال: قد يختلف موقع خلية حملية بعشرات الكيلومترات بين أعضاء المجموعة رغم اتفاقهم على بيئة غير مستقرة."},{"type":"callout","text":"خلاصة: النماذج الممثلة للحمل تحسن تمثيل بعض العمليات، لكنها لا تلغي عدم اليقين المحلي."}]}',1470,60,'["شرح مفهوم النماذج الممثلة للحمل","فهم أثر الدقة الأفقية","تمييز التمثيل الصريح عن المعلمة"]','النماذج العددية المتقدمة'),
('radar-data-assimilation','استيعاب بيانات الرادار في النماذج العددية','استخدام الانعكاسية والسرعة الشعاعية لتحسين التحليل الابتدائي.','{"blocks":[{"type":"text","text":"توفر بيانات الرادار معلومات مكانية وزمنية عالية التواتر عن الهطول وحركة الهواء ضمن مجال الرصد."},{"type":"text","text":"تمثل الانعكاسية شدة الإشارة المرتدة من الهيدروميتورات، وتستخدم لتشخيص مناطق الهطول وبنية العواصف."},{"type":"text","text":"تقيس السرعة الشعاعية مركبة حركة الهدف باتجاه الرادار أو بعيداً عنه، ولا تعطي متجه الرياح الكامل وحدها."},{"type":"text","text":"تستخدم ملاحظات السرعة الشعاعية في بعض أنظمة الاستيعاب لتحسين تقدير الرياح داخل العواصف والبيئة المحيطة."},{"type":"text","text":"يمكن أن تساعد الانعكاسية في تحديد مواقع الهيدروميتورات ومحتوى الماء السحابي وفق مشغل رصد مناسب."},{"type":"text","text":"تتأثر بيانات الرادار بالحجب والتوهين والضوضاء والأهداف غير الجوية والتداخلات الهندسية."},{"type":"text","text":"تحتاج البيانات إلى ضبط جودة وتصحيح الموقع والتوقيت ومعالجة أثر الأرض قبل الاستيعاب."},{"type":"text","text":"تربط مشغلات الرصد بين متغيرات النموذج والقياسات الرادارية، وقد تكون العلاقة غير خطية."},{"type":"text","text":"تختلف فاعلية الاستيعاب باختلاف نوع الرادار وتغطية الشبكة والبيئة الجوية ونظام النموذج."},{"type":"text","text":"يجب التحقق من أثر الاستيعاب على التنبؤ اللاحق وليس الاكتفاء بتحسن التحليل الأولي."},{"type":"text","text":"مثال: إدخال سرعات شعاعية متعددة الزوايا قد يحسن تقدير الرياح داخل نطاق التغطية مقارنة باستخدام محطة سطحية منفردة."},{"type":"callout","text":"خلاصة: الرادار مصدر غني للتهيئة قصيرة المدى، لكنه يحتاج معالجة جودة ومشغل رصد وتحققاً مستقلاً."}]}',1480,60,'["تمييز منتجات الرادار المستوعبة","فهم السرعة الشعاعية والانعكاسية","التعرف إلى قيود الاستيعاب"]','الاستيعاب المتقدم للبيانات'),
('satellite-data-assimilation','استيعاب بيانات الأقمار الصناعية في التنبؤ العددي','استيعاب القياسات الإشعاعية والرطوبة والحرارة من الأقمار المدارية.','{"blocks":[{"type":"text","text":"توفر الأقمار الصناعية تغطية واسعة ومتكررة للغلاف الجوي والمحيطات والمناطق قليلة المحطات."},{"type":"text","text":"قد تستوعب النماذج قياسات الإشعاع الطيفي مباشرة بدلاً من تحويلها أولاً إلى حرارة أو رطوبة مسترجعة."},{"type":"text","text":"تحتاج عملية الاستيعاب إلى مشغل رصد يحسب الإشعاع المتوقع من حالة النموذج للمقارنة بالقياس."},{"type":"text","text":"تختلف حساسية القنوات الطيفية للحرارة والرطوبة والسطح والسحب بحسب طول الموجة ووظيفة الاستجابة."},{"type":"text","text":"تؤثر السحب في تفسير كثير من القنوات، لذلك تستخدم اختبارات كشف السحب أو طرق مخصصة للبيانات الغائمة."},{"type":"text","text":"تحتاج القياسات إلى معايرة إشعاعية وتصحيح هندسي ومعلومات عن زاوية الرصد والسطح."},{"type":"text","text":"قد تستخدم قياسات الرطوبة المسترجعة أو الرياح المستنتجة من تتبع السحب في أنظمة الاستيعاب وفق نوع المنتج."},{"type":"text","text":"تؤثر أخطاء الخلفية والرصد والتمثيل في وزن القياس ضمن التحليل."},{"type":"text","text":"تساعد الأقمار ذات المدار الثابت في التغطية المتكررة، بينما توفر الأقمار القطبية تغطية عالمية ودقة مختلفة."},{"type":"text","text":"تراجع جودة الاستيعاب عبر مقارنة التحليل والتنبؤ بالمشاهدات المستقلة ومقاييس الأداء."},{"type":"text","text":"مثال: قناة حساسة لبخار الماء قد تضيف معلومات عن الطبقات المتوسطة والعليا، لكن تفسيرها يتطلب معرفة استجابتها الرأسية."},{"type":"callout","text":"خلاصة: استيعاب الأقمار يوسع التغطية الرصدية لكنه يعتمد على المعايرة ومشغلات الرصد وضبط الجودة."}]}',1490,60,'["شرح الاستيعاب الإشعاعي","فهم القنوات الطيفية","التعرف إلى أثر السحب والسطح"]','الاستيعاب المتقدم للبيانات'),
('ensemble-downscaling-and-localization','التصغير المكاني التجميعي والتوقعات المحلية','تحويل مخرجات النماذج واسعة النطاق إلى معلومات محلية احتمالية.','{"blocks":[{"type":"text","text":"يهدف التصغير المكاني إلى تحويل معلومات النماذج واسعة النطاق إلى تقديرات أدق مكانياً تناسب منطقة أو موقعاً محدداً."},{"type":"text","text":"يستخدم التصغير الديناميكي نموذجاً إقليمياً يحاكي العمليات الجوية على شبكة أدق ضمن مجال محدود."},{"type":"text","text":"يستخدم التصغير الإحصائي علاقات بين مخرجات النموذج والقياسات المحلية لتقدير المتغيرات على مقياس أدق."},{"type":"text","text":"تستفيد بعض الطرق من الارتفاع والتضاريس والغطاء الأرضي والخصائص الساحلية لتفسير الفروق المحلية."},{"type":"text","text":"قد يضيف التصغير تفاصيل واقعية، لكنه لا يزيل أخطاء النموذج العالمي أو عدم اليقين في الحالة الابتدائية."},{"type":"text","text":"يجب تقييم التصغير على فترات مستقلة ومحطات لم تدخل في بناء العلاقة الإحصائية."},{"type":"text","text":"تسمح مجموعات النماذج بتقدير توزيع احتمالي للقيم المحلية بدلاً من قيمة واحدة."},{"type":"text","text":"قد يؤدي التصغير إلى ثقة زائفة إذا لم تنقل مصادر عدم اليقين أو لم تتم معايرة الاحتمالات."},{"type":"text","text":"تختلف دقة التوقع المحلي بحسب المتغير؛ فالحرارة اليومية قد تكون أسهل من الهطول الحملي الموضعي في بعض البيئات."},{"type":"text","text":"تحتاج المنتجات المحلية إلى بيانات وصفية عن الموقع والارتفاع وفترة التوقع وطريقة التصغير."},{"type":"text","text":"مثال: تحويل توقع حرارة إقليمي إلى محطة جبلية يحتاج تصحيحاً للارتفاع والتحقق من أثر التعرض المحلي."},{"type":"callout","text":"خلاصة: التصغير مفيد عندما يحافظ على عدم اليقين ويخضع للتحقق المحلي المستقل."}]}',1500,60,'["شرح التصغير المكاني","فهم التصغير الديناميكي والإحصائي","تفسير احتمالات التوقع المحلي"]','النماذج العددية المتقدمة'),
('ai-machine-learning-weather-forecasting','مبادئ الذكاء الاصطناعي والتعلم الآلي في التنبؤ الجوي','أنواع التعلم والبيانات والميزات ومقارنة النماذج الإحصائية والفيزيائية.','{"blocks":[{"type":"text","text":"يستخدم التعلم الآلي أنماطاً مستخلصة من بيانات سابقة لبناء علاقة بين المدخلات والمخرجات أو لتصنيف الحالات."},{"type":"text","text":"يشمل التعلم الخاضع للإشراف التدريب على أمثلة لها قيم مرجعية، بينما يستكشف التعلم غير الخاضع للإشراف بنية البيانات دون تسميات مسبقة."},{"type":"text","text":"تحتاج تطبيقات الطقس إلى بيانات متزامنة ومكانية متسقة وتمثيل صحيح للوحدات والتوقيت."},{"type":"text","text":"قد تشمل الميزات مدخلات النماذج والقياسات السابقة والارتفاع والتضاريس ومؤشرات الموسم."},{"type":"text","text":"يجب تقسيم البيانات زمنياً إلى تدريب وتحقق واختبار لتجنب تسرب المستقبل إلى الماضي."},{"type":"text","text":"تختلف النماذج من الانحدار والغابات العشوائية إلى الشبكات العصبية والتعلم العميق."},{"type":"text","text":"قد يتعلم النموذج انحيازات شبكة الرصد أو خصائص فترة تدريب محدودة بدلاً من العلاقات الجوية القابلة للتعميم."},{"type":"text","text":"تحتاج التنبؤات الاحتمالية إلى معايرة وتقييم باستخدام مقاييس مناسبة للتوزيع والحدث."},{"type":"text","text":"يمكن استخدام التعلم الآلي كأداة مساعدة للنماذج العددية أو لتصحيح الانحياز أو تحليل الصور والبيانات."},{"type":"text","text":"لا يغني الذكاء الاصطناعي عن التحقق الفيزيائي ومراجعة الحالات المتطرفة والبيئات قليلة البيانات."},{"type":"text","text":"مثال: نموذج يتنبأ بالحرارة من مخرجات عددية ومحطات سابقة يجب اختباره على سنوات لم تدخل التدريب."},{"type":"callout","text":"خلاصة: نجاح التعلم الآلي في الأرصاد يعتمد على جودة البيانات والتصميم والتقسيم الزمني والتحقق."}]}',1510,60,'["شرح أنواع التعلم الآلي","فهم تجهيز البيانات الجوية","تمييز التنبؤ الفيزيائي عن التعلم الآلي"]','الذكاء الاصطناعي والأرصاد'),
('machine-learning-bias-correction','تصحيح انحياز النماذج الجوية بالتعلم الآلي','تدريب نماذج التصحيح والتحقق المستقل ومراقبة تغير الانحياز.','{"blocks":[{"type":"text","text":"قد تظهر انحيازات منتظمة في مخرجات النماذج بسبب التمثيل أو الشبكة أو الشروط الحدية أو خصائص المنطقة."},{"type":"text","text":"يستخدم تصحيح الانحياز علاقات تاريخية بين التوقعات والمشاهدات لتعديل المخرجات."},{"type":"text","text":"يمكن للتعلم الآلي تمثيل علاقات غير خطية بين المتغيرات المتوقعة والظروف المحلية."},{"type":"text","text":"تحتاج البيانات إلى مطابقة مكانية وزمنية دقيقة بين التوقع والمشاهدة الصحيحة."},{"type":"text","text":"يجب منع تسرب البيانات بين التدريب والاختبار، ويفضل التقسيم حسب السنوات أو الحالات المستقلة."},{"type":"text","text":"قد ينجح التصحيح في الظروف الشائعة ويفشل في الأحداث النادرة أو القيم خارج نطاق التدريب."},{"type":"text","text":"ينبغي اختبار أداء النموذج على الفصول المختلفة والمحطات الجديدة ومجالات القيم القصوى."},{"type":"text","text":"تستخدم مقاييس مثل MAE وRMSE والانحياز ومقاييس الاحتمالات قبل التصحيح وبعده."},{"type":"text","text":"قد يتغير انحياز النموذج عند تحديث الإصدار أو الشبكة أو الفيزياء، ولذلك يلزم رصد مستمر وإعادة تقييم."},{"type":"text","text":"يجب الاحتفاظ بالمخرجات الأصلية والمصححة وتوثيق إصدار نموذج التصحيح ومعاملاته."},{"type":"text","text":"مثال: تصحيح انحياز الحرارة في محطة واحدة لا يثبت نجاحه في محطة جبلية أخرى لم تدخل بياناتها في التدريب."},{"type":"callout","text":"خلاصة: التصحيح الآلي مفيد بشرط التحقق الزمني والمكاني ومراقبة الانجراف في الأداء."}]}',1520,60,'["شرح تصحيح الانحياز","فهم التدريب والتحقق الزمني","تمييز التصحيح عن تحسين المهارة"]','الذكاء الاصطناعي والأرصاد'),
('ai-satellite-cloud-classification','التصنيف الآلي للسحب والظواهر من صور الأقمار','استخدام التعلم العميق في تحليل الصور متعددة الأطياف وتتبع السحب.','{"blocks":[{"type":"text","text":"تستخدم نماذج الرؤية الحاسوبية لتحليل الصور الفضائية وتصنيف أنماط السحب والسطوح والظواهر الجوية."},{"type":"text","text":"قد تجمع المدخلات قنوات مرئية وتحت حمراء وبخار ماء وبيانات زاوية الرصد."},{"type":"text","text":"تحتاج بيانات التدريب إلى تسميات موثوقة تمثل أنواع السحب والظروف الموسمية والمناطق الجغرافية المختلفة."},{"type":"text","text":"تستطيع الشبكات الالتفافية استخراج أنماط مكانية من الصور، بينما تستفيد نماذج أخرى من التسلسل الزمني للصور."},{"type":"text","text":"تتطلب المقارنة بين الصور تصحيحاً هندسياً وتوحيداً في الدقة والتوقيت والمعايرة."},{"type":"text","text":"قد يخلط النموذج بين السحب العالية الرقيقة والسطوح الباردة أو بين الغبار والسحب في بعض الظروف."},{"type":"text","text":"تؤثر السحب المتعددة الطبقات والظلال والسطوح الساطعة في جودة التصنيف."},{"type":"text","text":"تستخدم مصفوفة الالتباس والدقة والاستدعاء ودرجات F1 لتقييم الفئات المختلفة."},{"type":"text","text":"قد تكون الدقة الإجمالية مضللة إذا كانت فئة شائعة تهيمن على عدد العينات."},{"type":"text","text":"ينبغي اختبار النموذج على أقمار أو مواسم أو مناطق لم تدخل في التدريب لتقييم التعميم."},{"type":"text","text":"مثال: نموذج يصنف السحب الركامية قد يحتاج إلى بيانات رادار وسبر للتحقق من العمق والنشاط الحملي."},{"type":"callout","text":"خلاصة: الذكاء الاصطناعي يعزز تحليل الصور لكنه يحتاج بيانات مرجعية وتمثيلاً متوازناً وتحققاً مستقلاً."}]}',1530,60,'["فهم تصنيف الصور الفضائية","التعرف إلى ميزات القنوات الطيفية","تقييم أخطاء التصنيف"]','الذكاء الاصطناعي والأرصاد'),
('ai-forecast-verification-and-explainability','التحقق من التنبؤات الذكية وقابلية تفسيرها','قياس أداء النماذج الذكية وفهم المتغيرات المؤثرة وحدود التفسير.','{"blocks":[{"type":"text","text":"يجب تقييم نماذج الذكاء الاصطناعي بمقاييس تحقق مناسبة لنوع المخرجات والمتغير والحدث."},{"type":"text","text":"تستخدم المقاييس المستمرة للأرقام مثل MAE وRMSE، بينما تستخدم مقاييس التصنيف للأحداث والفئات."},{"type":"text","text":"تحتاج النماذج الاحتمالية إلى مقاييس مثل Brier Score أو الدرجات الاحتمالية المناسبة بحسب نوع التوزيع."},{"type":"text","text":"تساعد اختبارات المعايرة على معرفة ما إذا كانت الاحتمالات المعلنة تتفق مع التكرار المرصود."},{"type":"text","text":"تهدف قابلية التفسير إلى توضيح العوامل أو الميزات التي أثرت في نتيجة النموذج وفق طريقة التحليل."},{"type":"text","text":"قد تستخدم أهمية الميزات أو خرائط الحساسية أو طرق SHAP لتفسير مساهمة المدخلات ضمن حدود الطريقة."},{"type":"text","text":"لا يعني ارتفاع أهمية ميزة أنها سبب فيزيائي مباشر للظاهرة؛ فقد تعكس ارتباطاً أو تحيزاً في البيانات."},{"type":"text","text":"يجب اختبار النماذج على حالات متطرفة ومناطق قليلة الرصد وفترات مناخية مختلفة."},{"type":"text","text":"قد يتدهور الأداء عند تغير المناخ أو أجهزة الرصد أو مخرجات النموذج أو مصادر البيانات."},{"type":"text","text":"ينبغي توثيق البيانات والتدريب والمعلمات والإصدارات وحدود الاستخدام ونتائج التحقق."},{"type":"text","text":"مثال: إذا اعتمد نموذج هطول على متغير موسمي بصورة مفرطة، فقد يفشل عند انتقاله إلى موسم أو منطقة مختلفة."},{"type":"callout","text":"خلاصة: التحقق والتفسير والشفافية شروط أساسية قبل إدخال نماذج الذكاء الاصطناعي في التشغيل."}]}',1540,60,'["تقييم نماذج التنبؤ الذكية","فهم قابلية التفسير","تمييز الارتباط عن السببية"]','الذكاء الاصطناعي والأرصاد'),
('operational-ai-governance-meteorology','حوكمة الذكاء الاصطناعي في مراكز الأرصاد','المراجعة البشرية والتوثيق ومراقبة الانحراف وإدارة المخاطر التشغيلية.','{"blocks":[{"type":"text","text":"تتطلب أنظمة الذكاء الاصطناعي التشغيلية تحديد مسؤوليات واضحة عن البيانات والنموذج والمنتج النهائي."},{"type":"text","text":"ينبغي توثيق الغرض من النموذج والمتغيرات المدخلة ومصادر البيانات ومجال الاستخدام والقيود المعروفة."},{"type":"text","text":"تحتاج المنتجات المؤثرة في السلامة العامة إلى مراجعة بشرية وإجراءات اعتماد واضحة قبل إصدارها."},{"type":"text","text":"يجب مراقبة تغير توزيع المدخلات ومعدلات الخطأ والأداء بحسب المنطقة والموسم والظاهرة."},{"type":"text","text":"قد يحدث انجراف البيانات عندما تتغير خصائص الرصد أو المناخ أو مصادر البيانات عن فترة التدريب."},{"type":"text","text":"ينبغي الاحتفاظ بإصدارات النموذج والبيانات والمعلمات ونتائج التحقق لتسهيل التدقيق وإعادة الإنتاج."},{"type":"text","text":"يجب وضع آلية للرجوع إلى النظام السابق أو المنتج التقليدي عند تعطل النموذج أو تراجع أدائه."},{"type":"text","text":"تحتاج المخرجات إلى تمييز واضح بين القياس والتوقع والنتيجة المولدة آلياً."},{"type":"text","text":"يجب تقييم العدالة المكانية في التغطية، فقد تكون النماذج أقل موثوقية في المناطق قليلة البيانات."},{"type":"text","text":"تحدد إجراءات التشغيل متى يسمح باستخدام المخرجات ومتى يلزم التصعيد إلى خبير أو مصدر بديل."},{"type":"text","text":"مثال: عند اكتشاف تغير مفاجئ في توزيع مدخلات النموذج، يوقف الاعتماد الآلي المنفرد حتى مراجعة الجودة والأداء."},{"type":"callout","text":"خلاصة: الحوكمة تجعل الذكاء الاصطناعي أداة مساعدة قابلة للمراجعة وليست بديلاً عن المسؤولية العلمية."}]}',1550,60,'["شرح الحوكمة التشغيلية","تحديد دور المراجع البشري","وضع ضوابط التحديث والمراقبة"]','الذكاء الاصطناعي والأرصاد'))
insert into public.academy_lessons(course_id,chapter_id,unit_id,slug,title,summary,content,published,sort_order,level,estimated_minutes,learning_objectives,chapter_title,unit_title)
select c.id,ch.id,case d.unit when 'النماذج العددية المتقدمة' then u1.id when 'الاستيعاب المتقدم للبيانات' then u2.id when 'الذكاء الاصطناعي والأرصاد' then u3.id end,d.slug,d.title,d.summary,d.content::jsonb,false,d.ord,'advanced',d.mins,d.objectives::jsonb,'النماذج العددية المتقدمة والذكاء الاصطناعي في الأرصاد',d.unit from d cross join c cross join ch cross join u1 cross join u2 cross join u3
on conflict(course_id,slug) do update set chapter_id=excluded.chapter_id,unit_id=excluded.unit_id,title=excluded.title,summary=excluded.summary,content=excluded.content,published=false,sort_order=excluded.sort_order,level=excluded.level,estimated_minutes=excluded.estimated_minutes,learning_objectives=excluded.learning_objectives,chapter_title=excluded.chapter_title,unit_title=excluded.unit_title;